package cl.bancoxyz.webbff;import java.util.*;import org.springframework.cloud.client.loadbalancer.LoadBalanced;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;@RestController @RequestMapping("/api/web") public class WebController{private final RestClient.Builder client;public WebController(@LoadBalanced RestClient.Builder c){client=c;}@GetMapping("/dashboard/{customerId}/{accountId}") public Map<String,Object> dashboard(@PathVariable long customerId,@PathVariable long accountId){RestClient r=client.build();Object customer=r.get().uri("http://customer-service/api/customers/{id}",customerId).retrieve().body(Object.class);Object account=r.get().uri("http://account-service/api/accounts/{id}",accountId).retrieve().body(Object.class);Object payments=r.get().uri("http://payment-service/api/payments").retrieve().body(Object.class);return Map.of("channel","web","customer",customer,"account",account,"payments",payments);}}